                identities.push((id, owner));
            }
            offset += page.items.len();
            receipts.push(DiscoveryReceipt {
                url,
                sha256: sha256_digest(&bytes),
                total: page.total_results,
                declarations: identities,
            });
            items.extend(page.items);
            if offset == page.total_results {
                break;
            }
        }
